static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    GridSampleAffineCustomTilingData tiling;

    const gert::Shape* in_shape = context->GetInputShape(0);
    auto origin = in_shape->GetOriginShape();
    uint32_t dims = origin.GetDimNum();
    uint32_t N = (dims >= 1) ? static_cast<uint32_t>(origin.GetDim(0)) : 1;
    uint32_t C = (dims >= 2) ? static_cast<uint32_t>(origin.GetDim(1)) : 1;
    uint32_t H = (dims >= 3) ? static_cast<uint32_t>(origin.GetDim(2)) : 1;
    uint32_t W = (dims >= 4) ? static_cast<uint32_t>(origin.GetDim(3)) : 1;

    uint64_t totalLen64 = origin.GetShapeSize();
    uint32_t totalLength = static_cast<uint32_t>(totalLen64);

    context->SetBlockDim(BLOCK_DIM);
    tiling.set_totalLength(totalLength);
    tiling.set_tileNum(TILE_NUM);
    tiling.set_N(N);
    tiling.set_C(C);
    tiling.set_H(H);
    tiling.set_W(W);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(),
                        context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t *currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;

    return ge::GRAPH_SUCCESS;
}
}

